$ErrorActionPreference='Stop'
$scratch=Join-Path $PSScriptRoot 'focused-evidence-438'
$destination=Join-Path $PSScriptRoot 'retained-438-01a11c7b/managed-438/focused-handoff'
$summary=Get-Content (Join-Path $scratch 'publication/summary.json') -Raw | ConvertFrom-Json
if($summary.head -ne '18cf84a2a4d5acc05ca14ecd2ddd861a1fe20b43' -or $summary.actualMaster -ne '547206a1b372b73fc95fc412ad453b8099440000') {throw 'Unexpected live source or target'}
if(@($summary.checks | Where-Object status -ne 'completed').Count) {throw 'CI remains pending'}
if(@($summary.checks | Where-Object conclusion -notin @('success','skipped')).Count) {throw 'CI requires disposition'}
$scope=Get-Content (Join-Path $PSScriptRoot 'retained-438-01a11c7b/managed-438/focused-followup/scope.json') -Raw | ConvertFrom-Json
$files=Get-Content (Join-Path $scratch 'publication/files.json') -Raw | ConvertFrom-Json
$commits=Get-Content (Join-Path $scratch 'publication/commits.json') -Raw | ConvertFrom-Json
$expectedParent=$summary.base
for($i=0;$i -lt $commits.Count;$i++) {
 if($commits[$i].sha -ne ($scope.commits[$i] -split ' ')[0] -or @($commits[$i].parents).Count -ne 1 -or $commits[$i].parents[0].sha -ne $expectedParent) {throw 'Published ordered commit ancestry differs'}
 $expectedParent=$commits[$i].sha
}
if(@(Compare-Object ($scope.files.file | Sort-Object) ($files.filename | Sort-Object)).Count) {throw 'Published scope differs'}
foreach($file in $files){$expected=$scope.files|Where-Object file -eq $file.filename;if($expected.added -ne $file.additions -or $expected.deleted -ne $file.deletions){throw ('Scope counts changed: '+$file.filename)}}
New-Item -ItemType Directory -Path $destination -Force | Out-Null
Copy-Item (Join-Path $scratch 'publication') (Join-Path $destination 'publication') -Recurse
foreach($name in @('final-mobile-ci.log','final-ci-watch.log','followup-public-readback.json','public-readback.json','pr459-status.json','remote-retention.txt')) {Copy-Item (Join-Path $scratch $name) (Join-Path $destination $name)}
Copy-Item (Join-Path $PSScriptRoot 'read-focused-publication.ps1') $destination
Copy-Item (Join-Path $PSScriptRoot 'package-focused-handoff.ps1') $destination
